}

function snapshot() {
  return {
    phase: state.phase,
    profile: state.profile,
    checkedAt: state.checkedAt,
    checkedCount: state.checkedCount,
    skippedCount: state.skippedCount,
    updates: state.updates,
    dismissed: state.dismissed,
    error: state.error,
    message: state.message,
